import '../styles/ShoppingList.css';
import Article from './Article';
import { itemList } from '../datas/itemList';
import { useState } from 'react';


function ShoppingList({ cart, updateCart }) {
  const sizeRange = ['M', 'L']

  function addToCart(name, price) {
    const existingItem = cart.find(item => item.name === name);
    if (existingItem) {
      const updatedCart = (cart.map((item) =>
        item.name === name ? { ...item, amount: item.amount + 1 } : item
      ));
      updateCart(updatedCart);
    } else {
      updateCart([...cart, { name, price, amount: 1 }]);
    }
  }

  return (
    <div className="shopping-list">
      <ul>
        {itemList.map((item) => (
          <li className='item' >
            {/* <Article {...item}/> */}
            <img className='item-cover' src={item.cover} alt={item.name} /><br />
            Name : {item.name}<br />
            {item.size && <span>Taille : {item.size}</span>}
            Comfort : {item.comfort}<br />
            Price : {item.price} €<br />
            {item.onSale && <span>En soldes !</span>}
            <button onClick={() => addToCart(item.name, item.price)}>Ajouter</button>
          </li>
        ))}
      </ul>
    </div>
  )
}




export default ShoppingList
